#!/bin/bash# ==============================================================================# CONFIGURATION# ==============================================================================# 1. Dossier source (L'image JLink générée par Maven)# Adaptez le nom si votre profil Maven génère "java-ui" au lieu de "java-ui-linux"SOURCE_DIR="target/java-ui-linux"# 2. Dossier de destination (Chemin RELATIF FIXE)# ".." remonte d'un cran vers la racine commune, puis descend dans l'autre projetDEST_DIR="../bash-app/modules/graphicInterface/runtime"# ==============================================================================# SCRIPT DE DÉPLOIEMENT# ==============================================================================# Se placer dans le dossier où se trouve ce script pour garantir que les chemins relatifs fonctionnentcd "$(dirname "$0")" || exitecho "🚀 Démarrage du déploiement..."echo "   Source      : $SOURCE_DIR"echo "   Destination : $DEST_DIR"echo "----------------------------------------"# 1. Vérification que la source existe (le build a-t-il été fait ?)if [ ! -d "$SOURCE_DIR" ]; then    echo "❌ Erreur : Le dossier source '$SOURCE_DIR' n'existe pas."    echo "   Avez-vous lancé './buildApp.sh' ?"    exit 1fi# 2. Préparation du dossier de destination# On vérifie si le dossier parent de la destination existe, sinon on le créePARENT_DIR=$(dirname "$DEST_DIR")if [ ! -d "$PARENT_DIR" ]; then    echo "📂 Création du dossier parent : $PARENT_DIR"    mkdir -p "$PARENT_DIR"fi# 3. Nettoyage de l'ancienne versionif [ -d "$DEST_DIR" ]; then    echo "🧹 Suppression de l'ancienne version dans la destination..."    rm -rf "$DEST_DIR"fi# 4. Copie des fichiersecho "📦 Copie de la nouvelle version..."# On copie le dossier source et on le renomme en destinationcp -r "$SOURCE_DIR" "$DEST_DIR"# 5. Vérification finaleif [ -f "$DEST_DIR/bin/java" ]; then    echo "----------------------------------------"    echo "✅ DÉPLOIEMENT TERMINÉ AVEC SUCCÈS !"    echo "   L'interface est à jour dans : $DEST_DIR"    echo "----------------------------------------"else    echo "❌ Erreur : La copie semble avoir échoué (exécutable non trouvé)."    exit 1fi